    t[265039] = { name = "Пишнота Сільвермуна", fen = "An old item found within Silvermoon's Great Vault.", fua = "Старий предмет, знайдений у Великому Сховищі Сільвермуна." }
    t[265401] = { name = "Антикварний Тускарський Чайник", fen = "A gem among Honnu's salvaged items: an intact antique tuskarr teapot. How she came to acquire it is a mystery.", fua = "Перлина серед врятованих речей Гонну: цілий антикварний тускарський чайник. Як він їй дістався — загадка." }
    t[268944] = { name = "Сувенірний Ідол Галаззі", fen = "A cheaply-made, mass-produced, but surprisingly accurate scale model of a Halazzi shrine idol made for tourists.", fua = "Дешева, масово виготовлена, але напрочуд точна зменшена модель ідола зі святині Галаззі, зроблена для туристів." }
    t[268945] = { name = "Сувенірна Маска Налоракка", fen = "A papier mache scale model of Nalorakk's stone mask. Sadly, it is glued to a stand.", fua = "Зменшена модель кам'яної маски Налоракка з пап'є-маше. На жаль, її приклеєно до підставки." }
    t[268946] = { name = "Сувенірний Брелок Джан'алая", fen = "A resin model of a Jan'alai mask in minature on a chain meant to keep keys together and tidy. It's a bit gauche.", fua = "Мініатюрна смоляна модель маски Джан'алая на ланцюжку, що має тримати ключі вкупі й до ладу. Дещо вульгарнувато." }
    t[268947] = { name = "Сувенірне Прес-пап'є зі Святинею Акіл'зона", fen = "A small model Akil'zon shrine under clear resin to commemorate your travels to Zul'Aman--if you survive.", fua = "Маленька модель святині Акіл'зона під прозорою смолою — на пам'ять про твої мандри до Зул'Аману... якщо виживеш." }
    t[268948] = { name = "Вишукані Антикварні Штори Сільвермуна", fen = "Exquisite fabric with very fine stitching.Too bad they are very out of fashion.", fua = "Вишукана тканина з дуже тонким шитвом. Шкода, що вони геть вийшли з моди." }
    t[268949] = { name = "Одинока Сільничка Земельників", fen = "Being sold solo because 'the earthen don't use pepper.' The veracity of this is questionable.", fua = "Продається окремо, бо «земельники не вживають перцю». Правдивість цього твердження сумнівна." }
    t[275436] = { name = "Загублене в часі сідло", fen = "Granted by the Midnight Keystone Myth: Season One achievement. Lindormi, in Silvermoon or the Timeways, would be interested in trading for this. Expires at the end of the season.", fua = "Надається за досягнення \"Міф ключових каменів Опівніч: Сезон перший\". Ліндормі в Сільвермуні або в Часоплинах зацікавиться обміном на це. Спливає наприкінці сезону." }
    t[275665] = { name = "Зміщена у Фазі Іграшка", fen = "A favorite of the purrkin on K'aresh.", fua = "Улюблена іграшка муркінів на К'ареші." }
end)
